public class EqualityProvider implements System.StubProvider {
    public Boolean recording=false;
    public Object expected;
    public List<Type> signature;
    public Boolean sameSignature;
    public Boolean sameArguments;
    public Boolean membership;
    public List<String> calls=new List<String>();
    public Object handleMethodCall(Object target,String method,Type output,List<Type> inputTypes,List<String> names,List<Object> args) {
        calls.add(method+'|'+inputTypes[0].getName()+'|'+output.getName());
        if(recording) { expected=args[0]; signature=inputTypes; return null; }
        sameSignature=signature==inputTypes;
        sameArguments=expected==args[0];
        Set<CensusKey> expectedKeys=(Set<CensusKey>)expected;
        Set<CensusKey> actualKeys=(Set<CensusKey>)args[0];
        membership=expectedKeys.contains(actualKeys.iterator().next());
        return sameSignature && sameArguments ? new List<String>{'ready'} : null;
    }
}

