@IsTest private class SetProviderProof {
 private static Map<String,Object> compare(Set<CensusKey> a,Set<CensusKey> b){
  Object left=a,right=b;
  return new Map<String,Object>{'operator'=>a==b,'method'=>a.equals(b),'boxedOperator'=>left==right,'boxedMethod'=>left.equals(right),'nestedList'=>new List<Object>{left}==new List<Object>{right},'leftSize'=>a.size(),'rightSize'=>b.size()};
 }
 private static void emit(Map<String,Object> value){System.assertEquals('SET_EQ_OBSERVATION',JSON.serialize(value),'SET_EQ_OBSERVATION');}
 @IsTest static void freshEquivalent(){
  CensusKey a=new CensusKey(17),b=new CensusKey(17);
  Set<CensusKey> left=new Set<CensusKey>{a};
  Set<CensusKey> right=new Set<CensusKey>(new List<CensusKey>{b});
  Map<String,Object> value=compare(left,right);value.put('scalarEqual',a.equals(b));value.put('membership',left.contains(b));emit(value);
 }
 @IsTest static void sameInstance(){
  CensusKey key=new CensusKey(17);emit(compare(new Set<CensusKey>{key},new Set<CensusKey>(new List<CensusKey>{key})));
 }
 @IsTest static void distinctValue(){emit(compare(new Set<CensusKey>{new CensusKey(17)},new Set<CensusKey>(new List<CensusKey>{new CensusKey(29)})));}
 @IsTest static void providerEquivalent(){
  EqualityProvider provider=new EqualityProvider();LookupPort port=(LookupPort)Test.createStub(LookupPort.class,provider);
  provider.recording=true;port.lookup(new Set<CensusKey>{new CensusKey(17)});provider.recording=false;
  List<String> value=port.lookup(new Set<CensusKey>(new List<CensusKey>{new CensusKey(17)}));
  emit(new Map<String,Object>{'sameSignature'=>provider.sameSignature,'membership'=>provider.membership,'sameArguments'=>provider.sameArguments,'responseNotNull'=>value!=null,'responseSize'=>value==null?null:value.size()});
 }
}
